count = 0
for x in range(100, 1000):
    a, b, c = str(x)
    if a <= b <= c:
        count += 1
print(count)

digits = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'

for base in range(2, 37):
    for x in digits[1:base]:
        for y in digits[1:base]:
            try:
                if int(f'5{x}16', base) + int(f'{x}{x}{x}5', base) == int(f'115{y}{y}', base):
                    print(int(f'{y}{x}{y}', base))
            except ValueError:
                pass

f = [0] * 48
for n in range(48):
    if n == 0:
        f[n] = 0
    elif n < 3:
        f[n] = 1
    else:
        f[n] = f[n - 2] + f[n - 1]
print(f[47] % 10000)

